// Pas nad promptem jako czysty plan: co powiedzieć w podpisie, kto stoi na
// płótnie i ile wierszy pas zabiera. register.ts tylko czyta stan i zamienia
// plan na elementy; literał modułu płótna zostaje tam.

import type { KruxActivity, KruxBubble, KruxCue, KruxHordeMember, KruxMoods } from '../types'
import type { ForgeOrc, ForgeProps } from './forge'
import { bubbleFor } from './mood'
import { ORC_GAP, ORC_WIDTH, bandColumns, canvasColumns } from './sprites'
import { restVerb } from './voice'

// Podpis z lewej, przerwa 2 kolumny, za nim płótno.
export const CAPTION_COLUMNS = 28
export const CAPTION_GAP = 2

// Krux i do trzech kumpli; reszta hordy liczona w podpisie.
const STAGE_MATES = 3

// Płótno z dymkiem: 3 wiersze dymka i 3 wiersze sceny. Niskie: sama scena.
const TALL_ROWS = 6
const LOW_ROWS = 3

export type BandInput = {
  working: boolean
  activity: KruxActivity | null
  // Uderzenia tury wybierają podpis spoczynku; suma sesji jest seedem dymka.
  strikes: number
  total: number
  moods: KruxMoods
  // Kumple, których silnik widzi jako `running`, w kolejności wejścia.
  members: readonly KruxHordeMember[]
  held: KruxBubble | null
  cues?: readonly KruxCue[]
  // Krux czeka na `Agent` z pierwszego planu.
  waiting: boolean
  // Ograniczony ruch w ustawieniach.
  still: boolean
  now: number
  columns: number
  rows: number
  // Czy powierzchnia potrafi narysować płótno `Client`.
  hasClient: boolean
}

export type BandPlan = {
  // Szara kreska nad pasem, gdy jest na nią wiersz.
  rule: boolean
  verb: string
  target: string
  // Wyłącznie ukryci kumple: „+N z hordy”, bez licznika uderzeń.
  tally: string
  // `null`: za wąsko albo za nisko na płótno — pas to jedna linia tekstu.
  stage: { props: ForgeProps; width: number; height: number } | null
}

export function bandPlan(input: BandInput): BandPlan {
  const { working, members } = input
  const room = input.columns - CAPTION_COLUMNS - CAPTION_GAP
  const fit = input.hasClient ? Math.floor((room + ORC_GAP) / (ORC_WIDTH + ORC_GAP)) : 0
  // Stała liczba prostokątów: płótno nie zmienia szerokości, gdy horda przychodzi i odchodzi.
  const slots = Math.max(1, Math.min(1 + STAGE_MATES, fit))
  const shown = members.slice(0, slots - 1)
  const hidden = members.length - shown.length
  // Krux czeka na wyniki hordy: w spoczynku albo w trakcie `Agent` na pierwszym planie.
  // Gdy kumpel już oddał zwój, róg z wywołania `Agent` zagrał: Krux odbiera zwój
  // tam, gdzie czekał, zamiast dąć od nowa.
  const handedBack = input.activity?.scene === 'horn' && (input.cues ?? []).some(cue => cue.kind === 'handoff' && cue.until > input.now)
  const lounging = handedBack || (members.length > 0 && (!working || input.waiting))
  const orcs: ForgeOrc[] = [
    { key: 'krux', face: 'Krux', scene: lounging ? 'lounge' : (input.activity?.scene ?? 'hammer'), mood: input.moods.faces.Krux, ...(!lounging && input.activity?.startedAt !== undefined ? { workAt: input.activity.startedAt } : {}) },
    ...shown.map(member => ({ key: member.agentId, face: member.mate, scene: member.scene, mood: member.mate ? input.moods.faces[member.mate] : ('calm' as const), ...(member.startedAt === undefined ? {} : { workAt: member.startedAt }) })),
  ]
  // Krok kumpla, którego już nie ma na scenie, nie wisi nad nikim.
  const gone = input.held?.kind === 'step' && !members.some(member => member.agentId === input.held!.key)
  const said = bubbleFor({ now: input.now, held: gone ? null : input.held, working, activity: input.activity, moods: input.moods, seed: input.total })
  const speaker = said === null ? undefined : orcs.find(orc => orc.key === said.key)
  // Wysokość pasa zależy tylko od miejsca, nie od tego, czy ktoś mówi.
  const tall = input.hasClient && input.rows >= TALL_ROWS + 1 && room >= canvasColumns(slots, true)
  const height = tall ? TALL_ROWS : input.rows >= LOW_ROWS && fit >= 1 ? LOW_ROWS : 0
  const inCanvas = tall && said !== null && speaker !== undefined
  const verb = lounging ? 'Krux czekać na hordę' : working ? (input.activity?.verb ?? 'Krux rozpalać palenisko') : restVerb(input.strikes, input.total)
  const spoken = said === null ? '' : said.speaker === 'Krux' ? said.text : `${said.speaker === 'ork' ? 'Ork' : said.speaker}: ${said.text}`
  const target = !inCanvas && spoken ? spoken : working ? (input.activity?.target ?? '') : ''
  const tally = hidden > 0 ? `+${hidden} z hordy` : ''
  // Kreska zabiera wiersz, więc staje tylko nad pasem, który mieści się cały.
  const rule = input.rows >= Math.max(1, height) + 1
  if (height === 0) return { rule, verb, target, tally, stage: null }
  const props: ForgeProps = {
    variant: 'band',
    scale: 1,
    still: input.still,
    // W spoczynku płótno stoi, chyba że na scenie kuje jeszcze agent w tle.
    rest: !working && shown.length === 0,
    slots,
    bubbleRows: tall,
    orcs,
    bubble: inCanvas ? { key: speaker!.key, text: said!.text, speaker: said!.speaker } : null,
    cues: (input.cues ?? []).filter(cue => cue.until > input.now),
    now: input.now,
  }
  return { rule, verb, target, tally, stage: { props, width: tall ? canvasColumns(slots, true) : bandColumns(slots), height } }
}

files.hooks/crew.ts:
// Scena poza Kruxem: kto z hordy na niej stoi, czyj dymek wisi i jakie znaki
// czekają na płótno. Każde zdarzenie to jedno przejście `crewAfter`; stan trzyma
// register.ts, jednym `update`. Kumpel mówi tylko wtedy, gdy stoi na scenie:
// o swoim kroku, o wyniku swojej roboty albo o zdarzeniu z kroniki.

import type { KruxActivity, KruxCrew, KruxCue, KruxEvent, KruxHordeMember, KruxLore } from '../types'
import { EVENT_HOLD_MS, EVENT_SPEAKER, eventLine, mateStep } from './mood'

export const EMPTY_CREW: KruxCrew = { members: [], bubble: null, cues: [] }

// Znaki starsze niż wtręt płótno już zagrało; tyle wystarczy na kilka zdarzeń naraz.
const CUES_KEPT = 8

export type CrewEvent =
  // Subagent z głównej pętli wbiega na scenę.
  | { kind: 'spawn'; member: KruxHordeMember }
  // Narzędzie albo faza kumpla (dumanie, pisanie): jego poza i dymek z krokiem, chyba że wisi świeży wtręt.
  | { kind: 'mate-tool'; agentId: string; doing: KruxActivity }
  // Narzędzie Kruxa: wtręt i reakcja Kruxa po zdarzeniu albo koniec dymka kumpla.
  | { kind: 'own-tool'; event: KruxEvent | null; lore: KruxLore; seed: number; failure?: string }
  // Wynik narzędzia kumpla: jego wtręt i reakcja na własną robotę; `lore` to kronika tego jednego wywołania.
  | { kind: 'mate-event'; agentId: string; event: KruxEvent; lore: KruxLore; seed: number; failure?: string }
  // Pętla kumpla skończona: oddaje zwój i schodzi ze sceny razem ze swoim krokiem.
  | { kind: 'mate-done'; agentId: string }
  // Silnik widzi jako `running` tylko tych; reszta schodzi bez zakończenia i bez zwoju.
  | { kind: 'running'; ids: ReadonlySet<string> }
  // Minął czas wtrętu.
  | { kind: 'expire' }

// Stan sprzed tej wersji nie ma znaków: brak to pusta lista.
function cuesOf(crew: KruxCrew): KruxCue[] {
  return crew.cues ?? []
}

function cued(crew: KruxCrew, cue: KruxCue, now: number): KruxCue[] {
  return [...cuesOf(crew).filter(old => old.until > now), cue].slice(-CUES_KEPT)
}

export function crewAfter(crew: KruxCrew, event: CrewEvent, now: number): KruxCrew {
  const { members, bubble } = crew
  switch (event.kind) {
    case 'spawn':
      return { ...crew, members: [...members.filter(other => other.agentId !== event.member.agentId), event.member] }
    case 'mate-tool': {
      const member = members.find(other => other.agentId === event.agentId)
      if (member === undefined) return crew
      // Róg zostaje dla Kruxa: kumpel, który sam woła hordę, dalej kuje.
      const scene = event.doing.scene === 'horn' ? 'hammer' : event.doing.scene
      const moved = members.map(other => (other === member ? { ...member, scene, target: event.doing.target, ...(event.doing.startedAt === undefined ? {} : { startedAt: event.doing.startedAt }) } : other))
      if (bubble?.kind === 'event' && bubble.until > now) return { ...crew, members: moved }
      return { ...crew, members: moved, bubble: { kind: 'step', key: member.agentId, speaker: member.mate ?? 'ork', text: mateStep(event.doing) } }
    }
    case 'own-tool': {
      if (event.event === null) return bubble?.kind === 'step' ? { ...crew, bubble: null } : crew
      const mate = EVENT_SPEAKER[event.event]
      const member = members.find(other => other.mate === mate)
      const text = eventLine(event.event, event.lore, event.seed, event.failure)
      const until = now + EVENT_HOLD_MS
      // Komentuje kumpel z pasującym fachem, ale reaguje ten, kto robił: Krux.
      const cues = cued(crew, { key: 'krux', kind: event.event, until }, now)
      return { ...crew, cues, bubble: member ? { kind: 'event', key: member.agentId, speaker: mate, text, until } : { kind: 'event', key: 'krux', speaker: 'Krux', text, until } }
    }
    case 'mate-event': {
      const member = members.find(other => other.agentId === event.agentId)
      if (member === undefined) return crew
      const text = eventLine(event.event, event.lore, event.seed, event.failure)
      const until = now + EVENT_HOLD_MS
      return { ...crew, cues: cued(crew, { key: member.agentId, kind: event.event, until }, now), bubble: { kind: 'event', key: member.agentId, speaker: member.mate ?? 'ork', text, until } }
    }
    case 'mate-done': {
      const left = members.filter(other => other.agentId !== event.agentId)
      if (left.length === members.length) return crew
      return {
        members: left,
        bubble: bubble?.kind === 'step' && bubble.key === event.agentId ? null : bubble,
        cues: cued(crew, { key: event.agentId, kind: 'handoff', until: now + EVENT_HOLD_MS }, now),
      }
    }
    case 'running': {
      const left = members.filter(other => event.ids.has(other.agentId))
      if (left.length === members.length) return crew
      return { ...crew, members: left, bubble: bubble?.kind === 'step' && !event.ids.has(bubble.key) ? null : bubble }
    }
    case 'expire': {
      const cues = cuesOf(crew)
      const fresh = cues.filter(cue => cue.until > now)
      const quiet = bubble?.kind === 'event' && bubble.until <= now
      if (!quiet && fresh.length === cues.length) return crew
      return { ...crew, bubble: quiet ? null : bubble, cues: fresh }
    }
  }
}

