import { SLIDE, STAND, at, draw, lerp, line, noise, pingPong, pusher, stander } from '../stage'
import type { Act, Frame, Layer } from '../stage'

// Kuźnia przy Edit i Write. Każdy warsztat wjeżdża z prawej z narzędziem na sobie,
// Krux sięga po nie i bierze się do roboty; przy zejściu odkłada narzędzie i warsztat odjeżdża.

// Stójka z ręką wyciągniętą przed siebie na wysokości fartucha.
const REACH: Frame = stander('mid', 'gg')

// ——— Kowadło ———
const POSES: Record<'up' | 'mid' | 'strike' | 'sparks', Frame> = {
  up: [
    '.gggg..SSS............',
    'grggrg..h.............',
    '.tggt...h.............',
    'bbbbbbgg..............',
    '.bGGb......ssRRRss....',
    '.G..G........sss......',
  ],
  mid: [
    '.gggg.................',
    'grggrg.....SS.........',
    '.tggt...hhhSS.........',
    'bbbbbbgg..............',
    '.bGGb......ssRRRss....',
    '.G..G........sss......',
  ],
  strike: [
    '.gggg........y...o....',
    'grggrg.....o...y......',
    '.tggt.........o.......',
    'bbbbbbgghhhhhSSS......',
    '.bGGb......ssRRRss....',
    '.G..G........sss......',
  ],
  sparks: [
    '.gggg.......o.....y...',
    'grggrg..........o.....',
    '.tggt.....y...........',
    'bbbbbbgghhhhhSSS......',
    '.bGGb......ssooRss....',
    '.G..G........sss......',
  ],
}

const CYCLE = ['up', 'up', 'mid', 'strike', 'sparks', 'mid', 'up', 'up'] as const
const ANVIL: Frame = ['ssRRRss', '..sss..']
const ANVIL_AT = 11

// Kowadło z młotem położonym na rozgrzanej sztabie.
const anvilAt = (x: number): Layer[] => [[ANVIL, x, 4], [['hhhhhSSS'], x - 3, 3]]

// Kowadło: wjeżdża z młotem na grzbiecie, Krux chwyta trzonek i unosi młot; pętla to zamach, uderzenie, iskry.
const anvil: Act = {
  name: 'kowadło',
  who: ['Krux', 'Grom'],
  intro: [
    ...SLIDE.map(dx => draw(...anvilAt(ANVIL_AT + dx), [STAND, 0, 0])),
    draw(...anvilAt(ANVIL_AT), [REACH, 0, 0]),
    POSES.mid,
  ],
  length: CYCLE.length,
  loop: t => POSES[CYCLE[t]!],
}

// ——— Hebel ———
const BENCH: Frame = ['hhhhhhhhhhhh', '.x........x.']
const BENCH_AT = 8
const PLANE: Frame = ['.x', 'xxS']

// Wiór z czoła hebla zwija się w górę i w prawo.
function shavings(t: number, at: (t: number) => number): Layer[] {
  const out: Layer[] = []
  for (let age = 0; age < 3; age += 1) {
    const born = t - age
    if (born < 1 || born > 8) continue
    out.push([[age === 0 ? 'j' : 'p'], at(born) + 11 + age, 2 - age])
  }
  return out
}

function planeLoop(t: number): Frame {
  // 16 klatek: pchnięcie przez 8 klatek z wiórami, powrót bez wiórów.
  const at = (s: number) => lerp(0, 3, pingPong(s, 8) / 8)
  const x = at(t)
  return draw([BENCH, BENCH_AT, 4], [PLANE, x + 8, 2], [pusher(x), x, 0], ...(t <= 8 ? shavings(t, at) : []))
}

const plane: Act = {
  name: 'hebel',
  intro: [
    // Kozioł z deską i heblem wjeżdża, Krux sięga po hebel.
    ...SLIDE.map(dx => draw([BENCH, BENCH_AT + dx, 4], [PLANE, BENCH_AT + dx, 2], [STAND, 0, 0])),
    draw([BENCH, BENCH_AT, 4], [PLANE, BENCH_AT, 2], [stander('mid', 'g'), 0, 0]),
  ],
  length: 16,
  loop: planeLoop,
}

// ——— Szlifierka ———
const WHEEL_AT = 13
const RIM: Frame = ['.qqq.', 'qcccq', 'qcScq', 'qcccq', '.qqq.']
// Osiem pól wokół piasty, w kolejności zegara.
const RING = [[1, 1], [2, 1], [3, 1], [3, 2], [3, 3], [2, 3], [1, 3], [1, 2]] as const

// Tarcza z dwiema kreskami naprzeciw siebie: obrót o pole na klatkę.
function wheel(x: number, turn: number): Layer[] {
  const marks = [turn % 8, (turn + 4) % 8].map(i => [['q'], x + RING[i]![0], RING[i]![1]] as Layer)
  return [[RIM, x, 0], ...marks, [['xxxxxxxxxxx'], x - 5, 5]]
}

// Ostrze: rękojeść 'x', klinga do lewej krawędzi tarczy.
const blade = (x: number, y: number): Layer => [['xssss'], x, y]

const pressing = (t: number) => t < 12

function grindSparks(t: number, frame: number): Layer[] {
  const out: Layer[] = []
  for (let age = 0; age < 4; age += 1) {
    const born = (t - age + 16) % 16
    if (!pressing(born)) continue
    const drift = noise(born, 1, 2) < 0.5 ? 0 : 1
    out.push([[noise(frame, age, 3) < 0.5 ? 'y' : 'o'], 12 - age - drift * Math.floor(age / 2), 2 - age])
  }
  return out
}

function grindLoop(t: number, frame: number): Frame {
  // 16 klatek: dociskać klingę do kręcącej się tarczy, iskry lecą w górę; potem odsunąć i obejrzeć.
  const on = pressing(t)
  return draw(...wheel(WHEEL_AT, t), [stander(on ? 'mid' : 'right', on ? 'gg' : 'g'), 0, 0], blade(on ? 8 : 7, 3), ...grindSparks(t, frame))
}

const grind: Act = {
  name: 'szlifierka',
  intro: [
    // Szlifierka z klingą na podstawie wjeżdża, tarcza toczy się po drodze.
    ...SLIDE.map((dx, i) => draw(...wheel(WHEEL_AT + dx, i), blade(8 + dx, 4), [STAND, 0, 0])),
    // Schylić rękę po klingę.
    draw(...wheel(WHEEL_AT, 7), blade(8, 4), [[...STAND.slice(0, 3), 'bbbbbbg', '.bGGb..g', STAND[5]!], 0, 0]),
  ],
  length: 16,
  loop: grindLoop,
}

// ——— Nity ———
const PLATES: Frame = ['sssSssSsss', '..x....x..']
const RIVET_SWING = [[9, 0], [9, 0], [10, 1], [11, 3], [11, 3], [10, 2], [9, 1], [9, 0],
  [10, 0], [11, 1], [12, 2], [14, 3], [14, 3], [13, 2], [11, 1], [10, 0]] as const

function rivetWork(x: number, y: number, strike = false): Frame {
  return draw(
    [PLATES, 9, 4], [STAND, 0, 0],
    ...line([5, 3], [7, 2], 'g'), ...line([6, 3], [8, 3], 'g'),
    ...line([8, 2], [x + 1, y + 1], 'h'), [['SSS'], x, y],
    ...(strike ? [at('y', x + 3, 2), at('o', x + 4, 1)] : []),
  )
}

// Nity: Grom chwyta młot obiema rękami i na zmianę zbija dwa łączenia blach.
const rivets: Act = {
  name: 'nity',
  who: ['Grom'],
  intro: [
    ...SLIDE.map(dx => draw([PLATES, 9 + dx, 4], [['hhhhhSSS'], 8 + dx, 2], [STAND, 0, 0])),
    draw([PLATES, 9, 4], [['hhhhhSSS'], 8, 2], [REACH, 0, 0]),
    rivetWork(11, 2), rivetWork(10, 1), rivetWork(9, 0),
  ],
  length: RIVET_SWING.length,
  loop: t => {
    const [x, y] = RIVET_SWING[t]!
    return rivetWork(x, y, t === 3 || t === 4 || t === 11 || t === 12)
  },
}

// ——— Poziomica ———
const LEVEL: Frame = ['ssiiiss', 'sssssss']
const LEVEL_BUBBLE = [0, 0, 1, 1, 1, 0, -1, -1, 0, 0, 0, 0] as const

function levelWork(t: number): Frame {
  return draw([BENCH, BENCH_AT + 2, 4], [LEVEL, 9, 2], at('y', 12 + LEVEL_BUBBLE[t]!, 2),
    [stander('right', 'ggg'), 0, 0],
    // Wolna dłoń puka w koniec poziomicy, bąbel wychyla się i wraca do środka.
    ...line([6, 3], t === 2 || t === 3 ? [9, 1] : [7, 3], 'g'))
}

// Poziomica: Ochra podnosi przyrząd z ławy, puka w ramkę i obserwuje bąbel.
const level: Act = {
  name: 'poziomica',
  who: ['Ochra'],
  intro: [
    ...SLIDE.map(dx => draw([BENCH, BENCH_AT + 2 + dx, 4], [LEVEL, 9 + dx, 3], at('y', 12 + dx, 3), [STAND, 0, 0])),
    draw([BENCH, BENCH_AT + 2, 4], [LEVEL, 9, 3], at('y', 12, 3), [REACH, 0, 0]),
    levelWork(0),
  ],
  length: LEVEL_BUBBLE.length,
  loop: levelWork,
}

// ——— Pilnik ———
const CLAMP: Frame = ['..s..', '..s..', '.SSS.', 'xxxxx']

function fileTool(dx: number, y: number): Layer[] {
  return [[['hh'], 7 + dx, y], ...line([9 + dx, y], [15 + dx, y + 1], 's')]
}

function fileWork(t: number): Frame {
  const dx = lerp(0, 2, pingPong(t, 8) / 8)
  const chips: Layer[] = []
  // Opiłki rodzą się na krawędzi przy pchnięciu, opadają przez dwie klatki.
  for (let age = 0; age < 2; age++) {
    const born = t - age
    if (born >= 2 && born <= 8) chips.push(at('m', 16 + age, 4 + age))
  }
  return draw([BENCH, BENCH_AT + 2, 4], [CLAMP, 13, 2],
    [stander('right'), 0, 0], ...line([6, 3], [7 + dx, 2], 'g'),
    ...fileTool(dx, 2), ...chips)
}

// Pilnik: ork zdejmuje narzędzie z ławy, wygładza stal w imadle; opiłki spadają.
const filing: Act = {
  name: 'pilnik',
  intro: [
    ...SLIDE.map(dx => draw([BENCH, BENCH_AT + 2 + dx, 4], [CLAMP, 13 + dx, 2], ...fileTool(dx, 3), [STAND, 0, 0])),
    draw([BENCH, BENCH_AT + 2, 4], [CLAMP, 13, 2], ...fileTool(0, 3), [stander('right', 'g'), 0, 0]),
    fileWork(0),
  ],
  length: 16,
  loop: fileWork,
}

// ——— Prasa śrubowa ———
const PRESS: Frame = ['SSSSSSSSS', 'S.......S', 'S.......S', 'S.......S', 'S.......S', 'xxxxxxxxx']
const PRESS_TURN = [2, 2, 1, 1, 2, 3, 3, 2, 2, 1, 1, 2, 3, 3, 2, 2] as const
const PRESS_DIE = [2, 2, 2, 2, 3, 3, 3, 3, 3, 3, 3, 3, 2, 2, 2, 2] as const

function screwPress(dx: number, turn: number, die: number): Layer[] {
  return [[PRESS, 12 + dx, 0], [['RRRRR'], 14 + dx, 4],
    ...line([8 + dx, turn], [19 + dx, 4 - turn], 'h'),
    ...line([16 + dx, 1], [16 + dx, die], 'q'), [['sss'], 15 + dx, die]]
}

function pressWork(t: number): Frame {
  const turn = PRESS_TURN[t]!
  return draw(...screwPress(0, turn, PRESS_DIE[t]!), [stander('right'), 0, 0],
    ...line([5, 3], [7, turn], 'g'),
    // Matryca dociska świeżą stal; iskra rodzi się przy zejściu śruby.
    ...(t === 4 ? [at('y', 18, 3)] : t === 5 ? [at('o', 19, 2)] : []))
}

// Prasa śrubowa: Grom zamiast łatać odlew tłoczy nową sztabę, kręcąc poprzeczką prasy.
const pressingSteel: Act = {
  name: 'prasa śrubowa',
  who: ['Grom'],
  intro: [
    ...SLIDE.map(dx => draw(...screwPress(dx, 2, 2), [STAND, 0, 0])),
    draw(...screwPress(0, 2, 2), [REACH, 0, 0]),
    pressWork(0),
  ],
  length: PRESS_TURN.length,
  loop: pressWork,
}

// ——— Złocenie ———
const GILT_PANEL: Frame = ['yyyyy', 'yWWWy', 'yWiWy', 'yyyyy']
const GILT_PATH = [[12, 2], [12, 2], [12, 3], [12, 4], [13, 4], [14, 4], [15, 4], [16, 4],
  [16, 3], [16, 2], [16, 2], [15, 2], [14, 2], [13, 2], [12, 2], [12, 2]] as const

function gildingProps(dx: number): Layer[] {
  return [[GILT_PANEL, 12 + dx, 1], [['.x.x.'], 12 + dx, 5], [['.yy.', 'kyyk'], 18 + dx, 4]]
}

// Drewniany trzonek, biała skuwka i złota farba na czubku pędzla.
function giltBrush(tip: number, y: number): Layer[] {
  return [[['hhhj'], tip - 4, y], at('y', tip, y)]
}

function gildingWork(t: number): Frame {
  const [tip, y] = GILT_PATH[t]!
  const x = tip - 12
  const orc: Frame = [...stander('right').slice(0, 5), pusher(x)[5]!]
  return draw(...gildingProps(0), [orc, x, 0],
    ...line([x + 5, 3], [tip - 5, y], 'g'), ...giltBrush(tip, y))
}

// Złocenie: Ochra prowadzi pędzel po obu brzegach panelu, pilnując jednakowego koloru i szerokości.
const gilding: Act = {
  name: 'złocenie',
  who: ['Ochra'],
  intro: [
    ...SLIDE.map(dx => draw(...gildingProps(dx), ...giltBrush(11 + dx, 3), [STAND, 0, 0])),
    draw(...gildingProps(0), ...giltBrush(11, 3), [stander('right', 'g'), 0, 0]),
    gildingWork(0),
  ],
  length: GILT_PATH.length,
  loop: gildingWork,
}

// Miech dmucha w palenisko, więc gra w scenie budowania (`build.ts`), nie przy kowadle.
export const HAMMER_ACTS: Act[] = [anvil, plane, grind, rivets, level, filing, pressingSteel, gilding]

files.hooks/acts/horn.ts:
import { STAND, draw, lerp, line, pingPong, stander } from '../stage'
import type { Act, Frame, Layer } from '../stage'

// Wezwanie hordy przy Agent. Rekwizyt przylatuje z prawej albo spada z góry, Krux go łapie
// i daje sygnał; prawdziwa horda wbiega potem z prawej krawędzi.

// Fala dźwięku: łuk z trzech pikseli wędruje w prawo od `from`.
function wave(from: number, age: number, cell: string): Layer {
  return [[cell, '.' + cell, cell], from + age, 1]
}

// ——— Róg ———
const HORN_ORC: Frame = ['.gggg....', 'grggrg..t', '.tggtttt', 'bbbbbbggt', '.bGGb....', '.G..G....']
const HORN_PROP: Frame = ['...t', 'ttt.', '...t']
const HORN_FRAMES = 24

function hornLoop(t: number): Frame {
  // 24 klatki: co cztery klatki nowa fala, na przemian pomarańczowa i żółta.
  const waves: Layer[] = []
  for (let born = 0; born <= 8; born += 4) if (t >= born) waves.push(wave(10, t - born, born % 8 === 0 ? 'o' : 'y'))
  return draw([HORN_ORC, 0, 0], ...waves)
}

// Krux patrzy, jak róg leci łukiem z prawej; łapie go oburącz i przykłada do ust.
const LOOK: Frame = stander('right')
const HORN_ARC = [[19, 3], [16, 1], [13, 0], [10, 0], [8, 1]] as const

const horn: Act = {
  name: 'róg',
  intro: [
    ...HORN_ARC.map(([x, y]) => draw([LOOK, 0, 0], [HORN_PROP, x, y])),
    draw([LOOK, 0, 0], [['', '', '', '......gg'], 0, 0], [HORN_PROP, 6, 2]),
    draw([HORN_ORC, 0, 0]),
  ],
  length: HORN_FRAMES,
  loop: hornLoop,
}

// ——— Bęben ———
const DRUM: Frame = ['jjjjjj', 'dxddxd', 'ddxxdd']
const DRUM_AT = 9

type Beat = 'up' | 'mid' | 'down'

// Pałka w dłoni: ręka unosi się do (7, 2), pałka sterczy w górę albo leży na skórze.
const STICK: Record<Beat, readonly (readonly [number, number])[]> = {
  up: [[8, 1], [9, 0]],
  mid: [[8, 1], [9, 1]],
  down: [[8, 2], [9, 2]],
}

function drummer(beat: Beat): Layer[] {
  return [[STAND, 0, 0], ...line([6, 3], [7, 2], 'g'), ...STICK[beat].map(([x, y]) => [['h'], x, y] as Layer)]
}

const DRUM_CYCLE: readonly Beat[] = ['down', 'mid', 'up', 'up', 'mid', 'down', 'mid', 'up', 'up', 'up', 'up', 'mid']
const HITS = [0, 5]

function drumLoop(t: number): Frame {
  // 12 klatek: dwa uderzenia, po każdym skóra błyska, a fala idzie w prawo.
  const n = DRUM_CYCLE.length
  const waves = HITS.map(hit => (t - hit + n) % n)
    .filter(age => age < 6)
    .map(age => wave(DRUM_AT + 7, age, age < 3 ? 'y' : 'o'))
  const flash: Layer[] = HITS.includes(t) ? [[['yy'], DRUM_AT + 1, 3]] : []
  return draw([DRUM, DRUM_AT, 3], ...flash, ...drummer(DRUM_CYCLE[t]!), ...waves)
}

const drum: Act = {
  name: 'bęben',
  intro: [
    // Bęben spada z góry z pałką na skórze, podskakuje i staje; Krux sięga po pałkę.
    ...[-3, -1, 1, 2, 3].map(y => draw([DRUM, DRUM_AT, y], [['hh'], 8, y - 1], [stander(y < 1 ? 'mid' : 'right'), 0, 0])),
    draw([DRUM, DRUM_AT, 3], [['hh'], 8, 2], [STAND, 0, 0], [['g'], 6, 3]),
  ],
  length: DRUM_CYCLE.length,
  loop: drumLoop,
}

// ——— Flaga ———
const FLAG_X = 8
// Wierzchołki drzewca od pionu do przechyłu w prawo; drzewce zawsze wychodzi z dłoni (8, 3).
const TOPS = [[8, 0], [9, 0], [10, 0], [11, 1], [11, 2]] as const

// Płachta przy wierzchołku łopocze: brzeg faluje co klatkę.
function cloth(x: number, y: number, frame: number): Layer {
  return [Math.floor(frame / 2) % 2 === 0 ? ['ddd', 'dd'] : ['dd', 'ddd'], x + 1, y]
}

function flagLoop(t: number): Frame {
  // 16 klatek: machać flagą od pionu do przechyłu i z powrotem.
  const [x, y] = TOPS[lerp(0, TOPS.length - 1, pingPong(t, 8) / 8)]!
  return draw([stander('mid', 'gg'), 0, 0], ...line([FLAG_X, 3], [x, y], 'h'), cloth(x, y, t))
}

// Flaga w pionie z drzewcem od `top` w dół na `length` pikseli.
const planted = (top: number, length: number, frame: number): Layer[] => [[Array(length).fill('h'), FLAG_X, top], cloth(FLAG_X, top, frame)]

const flag: Act = {
  name: 'flaga',
  intro: [
    // Flaga spada z nieba i wbija się w ziemię obok Kruxa.
    ...[-5, -3, -1, 1, 2].map((top, i) => draw([stander(top < 0 ? 'mid' : 'right'), 0, 0], ...planted(top, 4, i))),
    // Chwycić drzewce i wyrwać je z ziemi.
    draw([stander('mid', 'gg'), 0, 0], ...planted(2, 4, 5)),
    draw([stander('mid', 'gg'), 0, 0], ...planted(1, 3, 6)),
  ],
  length: 16,
  loop: flagLoop,
}

export const HORN_ACTS: Act[] = [horn, drum, flag]

files.hooks/acts/pick.ts:
import { SLIDE, STAND, at, croucher, draw, line, noise, pusher, stander } from '../stage'
import type { Act, Frame, Layer, Look, Point } from '../stage'

// Kopalnia przy Bash. Skała wyrasta z ziemi albo przesuwa się z prawej z narzędziem w sobie,
// Krux chwyta trzonek i bierze się do roboty; przy zejściu wbija narzędzie z powrotem i skała odchodzi.

// Stójka z ręką do połowy wyciągniętą: tak Krux sięga po trzonek.
const HALF: Frame = stander('mid', 'g')

// ——— Kilof ———
const PICK: readonly Frame[] = [
  [
    '.gggg.SSS.............',
    'grggrg.h........kkk...',
    '.tggt..h.......kkkkk..',
    'bbbbbbgg.......kkkkkk.',
    '.bGGb..........kkkkkkk',
    '.G..G.........kkkkkkkk',
  ],
  [
    '.gggg.................',
    'grggrg.....S....kkk...',
    '.tggt...hhhS...kkkkk..',
    'bbbbbbgg...S...kkkkkk.',
    '.bGGb..........kkkkkkk',
    '.G..G.........kkkkkkkk',
  ],
  [
    '.gggg........k..y.....',
    'grggrg......o...kkk...',
    '.tggt.........Skkkkk..',
    'bbbbbbgghhhhhhSkkkkkk.',
    '.bGGb.........Skkkkkkk',
    '.G..G.........kkkkkkkk',
  ],
  [
    '.gggg.....k.......o...',
    'grggrg.........ykkk...',
    '.tggt.......k.okkkkk..',
    'bbbbbbgghhhhhhSkkkkkk.',
    '.bGGb.........Skkkkkkk',
    '.G..G.........kkkkkkkk',
  ],
]

const PICK_CYCLE = [0, 0, 1, 2, 3, 1, 0, 0] as const
const ROCK: Frame = ['..kkk...', '.kkkkk..', '.kkkkkk.', '.kkkkkkk', 'kkkkkkkk']
// Kilof wbity w skałę: trzonek wystaje w stronę Kruxa.
const STUCK: Frame = ['......S', 'hhhhhhS', '......S']

// Skała wyrasta z ziemi o `sink` pikseli niżej, z kilofem w środku.
const rockAt = (sink: number): Layer[] => [[ROCK, 14, 1 + sink], [STUCK, 8, 2 + sink]]

// Kilof: skała wyrasta z ziemi z wbitym kilofem, Krux wyrywa go; pętla to zamach, uderzenie, odłamki.
const rock: Act = {
  name: 'kilof',
  intro: [
    ...[4, 3, 2, 1, 0].map(sink => draw(...rockAt(sink), [STAND, 0, 0])),
    draw(...rockAt(0), [HALF, 0, 0]),
    draw(...rockAt(0), [stander('mid', 'gg'), 0, 0]),
    PICK[1]!,
  ],
  length: PICK_CYCLE.length,
  loop: t => PICK[PICK_CYCLE[t]!]!,
}

// ——— Łopata i wózek ———
const HEAP: Frame = ['.qq.', 'qyqq']
const HEAP_AT = 8
const CART: Frame = ['s....s', 'ssssss', '.c..c.']
const CART_AT = 14
const RAILS = 13
// Urobek w wózku po każdym rzucie.
const LOADS: readonly Frame[] = [[], ['', '..qq'], ['', '.qqqq'], ['..y', '.qqqq', '']]

type Spade = { hand: readonly [number, number]; tip: readonly [number, number]; blade: readonly [number, number]; load: boolean }

// Postawy łopaty: ręka, koniec trzonka, ostrze; `load` to grudka na ostrzu.
const SPADE = {
  dig: { hand: [7, 3], tip: [8, 4], blade: [9, 5], load: false },
  lift: { hand: [7, 3], tip: [8, 3], blade: [9, 3], load: true },
  raise: { hand: [7, 2], tip: [8, 1], blade: [9, 1], load: true },
  thrown: { hand: [7, 2], tip: [8, 1], blade: [9, 1], load: false },
  mid: { hand: [7, 3], tip: [8, 3], blade: [9, 3], load: false },
  low: { hand: [7, 3], tip: [8, 4], blade: [9, 4], load: false },
} as const satisfies Record<string, Spade>

function spade(s: Spade): Layer[] {
  const arm = line([6, 3], s.hand, 'g')
  const handle = line(s.hand, s.tip, 'h').slice(1)
  const blade: Layer = [['SS'], s.blade[0], s.blade[1]]
  return [[STAND, 0, 0], ...arm, ...handle, blade, ...(s.load ? [[['qq'], s.blade[0], s.blade[1] - 1] as Layer] : [])]
}

// Jeden rzut: wbić, podważyć, unieść, rzucić; grudka leci łukiem do wózka.
const THROW: readonly (keyof typeof SPADE)[] = ['dig', 'dig', 'lift', 'raise', 'thrown', 'mid', 'low', 'low']
const FLIGHT: readonly (readonly [number, number] | null)[] = [null, null, null, null, [12, 0], [14, 1], [16, 2], null]

const railsAt = (x: number): Layer => [['S'.repeat(22 - RAILS)], x, 5]
const cartAt = (x: number, load: number): Layer[] => [[CART, x, 3], [LOADS[load]!, x, 2]]

function shovelLoop(t: number): Frame {
  // 40 klatek: trzy rzuty do wózka, pełny wózek odjeżdża w prawo i wraca pusty.
  if (t < 24) {
    const k = t % 8
    const load = Math.floor(t / 8) + (k === 7 ? 1 : 0)
    const lump = FLIGHT[k]
    return draw([HEAP, HEAP_AT, 4], railsAt(RAILS), ...cartAt(CART_AT, load), ...spade(SPADE[THROW[k]!]), ...(lump ? [[['q'], lump[0], lump[1]] as Layer] : []))
  }
  const away = t < 32 ? t - 23 : 40 - t
  return draw([HEAP, HEAP_AT, 4], railsAt(RAILS), ...cartAt(CART_AT + away, t < 32 ? 3 : 0), ...spade(SPADE.low))
}

// Łopata wbita w kopczyk, trzonek oparty skośnie.
const leaning = (sink: number): Layer[] => [[HEAP, HEAP_AT, 4 + sink], ...line([8, 1 + sink], [9, 3 + sink], 'h'), [['S'], 9, 4 + sink]]

const shovel: Act = {
  name: 'łopata',
  intro: [
    // Kopczyk rudy wyrasta z ziemi z łopatą w środku.
    ...[2, 1, 0].map(sink => draw(...leaning(sink), [STAND, 0, 0])),
    // Szyny z pustym wózkiem wjeżdżają z prawej.
    ...SLIDE.map(dx => draw(...leaning(0), railsAt(RAILS + dx), ...cartAt(CART_AT + dx, 0), [STAND, 0, 0])),
    // Chwycić trzonek.
    draw(...leaning(0), railsAt(RAILS), ...cartAt(CART_AT, 0), [STAND, 0, 0], [['g'], 6, 3], [['g'], 7, 2]),
    draw([HEAP, HEAP_AT, 4], railsAt(RAILS), ...cartAt(CART_AT, 0), ...spade(SPADE.low)),
  ],
  length: 40,
  loop: shovelLoop,
}

// ——— Świder ———
const WALL: Frame = ['..kkqkk', '.kkkkkq', 'kkqkkkk', 'kkkkkyk', 'kkkkqkk', 'kkkkkkk']
const WALL_AT = 15
const RUBBLE: Layer = [['qq'], WALL_AT - 2, 5]

// Świder: oprawa przy dłoni, trzon do ściany (dalej chowa go skała), korba w czterech położeniach:
// w górze, z przodu, w dole, z tyłu.
const CRANK: readonly Frame[] = [['h', 'h'], ['', '', 'x'], ['', '', '', 'h', 'h'], ['', '', 'x']]

function drill(x: number, turn: number): Layer[] {
  return [[['xssssss'], x, 3], [CRANK[turn % 4]!, x + 2, 1]]
}

// Pył sypie się spod wiertła, kiedy kręci się korba.
function dust(t: number): Layer[] {
  const out: Layer[] = []
  for (let age = 0; age < 2; age += 1) {
    const born = t - age
    if (born < 0 || born >= 16 || born % 2 === 1) continue
    out.push([[noise(born, 2, 5) < 0.5 ? 'q' : 'm'], WALL_AT - 1, 4 + age])
  }
  return out
}

function drillLoop(t: number): Frame {
  // 20 klatek: kręcić korbą i wchodzić w skałę piksel co pięć klatek, potem wyciągnąć świder.
  const x = t < 16 ? Math.floor(t / 5) : 19 - t
  const turn = t < 16 ? t : 0
  return draw(RUBBLE, ...drill(x + 8, turn), [WALL, WALL_AT, 0], [pusher(x), x, 0], ...dust(t))
}

const auger: Act = {
  name: 'świder',
  intro: [
    // Ściana z wbitym świdrem przesuwa się z prawej, Krux sięga po oprawę.
    ...SLIDE.map(dx => draw([RUBBLE[0], WALL_AT - 2 + dx, 5], ...drill(8 + dx, 0), [WALL, WALL_AT + dx, 0], [STAND, 0, 0])),
    draw(RUBBLE, ...drill(8, 0), [WALL, WALL_AT, 0], [HALF, 0, 0]),
  ],
  length: 20,
  loop: drillLoop,
}

// ——— Podkop Lonta ———
// Lont w przykucu podkopuje głaz małym kilofkiem, wyjmuje z fartucha laskę dynamitu, wsuwa ją
// w dołek, aż z ziemi wystaje sam lont, i kiwa głową. Głaz z ładunkiem zapada się w ziemię,
// na jego miejscu wyrasta nowy, a Lont podnosi kilofek do kolejnego podkopu.
const BOULDER: Frame = ['..kkk.', '.kkqkk', 'kkkkkq', 'kqkkkk']
const BOULDER_AT = 10
// Dołek pod głazem rośnie piksel po pikselu przy każdym uderzeniu.
const HOLE: readonly Point[] = [[10, 5], [11, 5], [12, 5]]

// Głaz `sink` pikseli pod ziemią z wykopanymi `dug` pikselami dołka i ładunkiem `charge`.
function boulder(sink: number, dug = 0, charge: readonly Layer[] = [], dx = 0): Layer[] {
  const hole = HOLE.slice(0, dug)
  // Dołek wycina piksele z głazu; ładunek siedzi w dołku i opada razem z głazem.
  const cut = draw([BOULDER, BOULDER_AT, 2]).map((row, y) =>
    [...row].map((cell, x) => (hole.some(([hx, hy]) => hx === x && hy === y) ? '.' : cell)).join(''))
  return [[cut, dx, sink], ...charge.map(([sprite, x, y]) => [sprite, x + dx, y + sink] as Layer)]
}

// Lont w przykucu; dłoń w punkcie `hand`, ręka od fartucha.
function crouched(look: Look, hand: Point | null): Layer[] {
  return [[croucher(look), 0, 0], ...(hand === null ? [] : line([6, 4], hand, 'g'))]
}

// Kilofek w dłoni: trzonek od dłoni do obucha.
function trowel(hand: Point, head: Point): Layer[] {
  return [...crouched('right', hand), ...line(hand, head, 'h').slice(1), at('S', head[0], head[1])]
}
const RAISED: Layer[] = trowel([7, 3], [8, 1])
const strike = (target: Point): Layer[] => trowel([8, 4], [target[0] - 1, target[1]])
// Kilofek odłożony na ziemię przy kolanie.
const DROPPED: Layer[] = [at('h', 6, 5), at('S', 7, 5)]

// Laska w dołku: czerwień w ziemi, lont sterczy przed głazem.
const PLANTED: Layer[] = [at('d', 11, 5), at('d', 12, 5), at('h', 9, 5), at('h', 9, 4)]

function undermining(t: number): Frame {
  // 0–5: zamach i uderzenie trzy razy, dołek rośnie, odłamki pryskają w górę.
  if (t < 6) {
    const k = Math.floor(t / 2)
    if (t % 2 === 0) return draw(...boulder(0, k), ...RAISED, ...(k > 0 ? [at('q', 9, 2), at('k', 11, 0)] : []))
    return draw(...boulder(0, k + 1), ...strike(HOLE[k]!), at('q', HOLE[k]![0] - 1, 3))
  }
  // 6: odłożyć kilofek; 7: sięgnąć do fartucha; 8: laska w dłoni.
  if (t === 6) return draw(...boulder(0, 3), ...DROPPED, ...crouched('right', [7, 4]))
  if (t === 7) return draw(...boulder(0, 3), ...DROPPED, ...crouched('mid', null), at('g', 5, 4))
  if (t === 8) return draw(...boulder(0, 3), ...DROPPED, ...crouched('right', [6, 4]), [['dd'], 7, 4], at('h', 6, 5))
  // 9–10: wsunąć laskę w dołek; 11: zostaje sam lont, kiwnąć głową.
  if (t === 9) return draw(...boulder(0, 3, [[['dd'], 9, 5]]), ...DROPPED, ...crouched('right', [8, 4]), at('h', 8, 5))
  if (t === 10) return draw(...boulder(0, 3, PLANTED), ...DROPPED, ...crouched('right', [8, 4]))
  if (t === 11) return draw(...boulder(0, 3, PLANTED), ...DROPPED, ...crouched('mid', null))
  // 12–13: głaz z ładunkiem zapada się w ziemię; 14–15: wyrasta nowy, Lont bierze kilofek.
  if (t < 14) return draw(...boulder(t === 12 ? 2 : 4, 3, PLANTED), ...DROPPED, ...crouched('right', t === 13 ? [7, 4] : null))
  return draw(...boulder(t === 14 ? 2 : 1), ...trowel([7, 4], t === 14 ? [8, 5] : [8, 3]))
}

const undermine: Act = {
  name: 'podkop',
  who: ['Lont'],
  intro: [
    // Głaz z kilofkiem u stóp wjeżdża z prawej.
    ...SLIDE.map(dx => draw(...boulder(0, 0, [], dx), ...DROPPED.map(([s, x, y]) => [s, x + dx, y] as Layer), [STAND, 0, 0])),
    draw(...boulder(0), ...DROPPED, [stander('right'), 0, 0]),
    // Przykucnąć, chwycić kilofek i unieść go.
    draw(...boulder(0), ...DROPPED, ...crouched('right', [7, 4])),
    draw(...boulder(0), ...trowel([7, 4], [8, 5])),
    draw(...boulder(0), ...trowel([7, 4], [8, 3])),
    draw(...boulder(0), ...RAISED),
  ],
  length: 16,
  loop: undermining,
}

// ——— Rozpierak Lonta ———
// Dwie połówki skały ze stalowym rozpierakiem w szczelinie wjeżdżają razem. Lont wykonuje
// trzy próbne ruchy pompką, dopiero za trzecim rozszerza szczelinę; odpuszcza zawór i zbiera siły.
const SPLIT_LEFT: Frame = ['.kq', '.kk', 'qkk', 'kqk']
const SPLIT_RIGHT: Frame = ['qk.', 'kk.', 'kqk', 'qkk']
const PUMP_AT = 9
const PUMP_DOWN = [0, 1, 0, 1, 0, 1, 2, 2, 1, 0, 0, 0, 0, 0, 0, 0] as const
const SPLIT_GAP = [0, 0, 0, 0, 0, 0, 1, 2, 2, 2, 2, 1, 1, 0, 0, 0] as const

// Pompa po lewej, przewód przy ziemi, teleskopowa stal między połówkami głazu.
function splitterAt(dx: number, gap = 0, down = 0): Layer[] {
  return [
    [SPLIT_LEFT, 14 + dx - gap, 2], [SPLIT_RIGHT, 17 + dx + gap, 2],
    [['xxx', 'xsx'], PUMP_AT + dx, 4],
    ...line([PUMP_AT + 1 + dx, 5], [17 + dx, 5], 'n'),
    ...line([15 + dx - gap, 4], [18 + dx + gap, 4], 's'),
    ...line([PUMP_AT + 1 + dx, 2 + down], [PUMP_AT + 1 + dx, 4], 's'),
    [['hhh'], PUMP_AT + dx, 1 + down],
  ]
}

function splitting(t: number): Frame {
  const down = PUMP_DOWN[t]!
  const gap = SPLIT_GAP[t]!
  // 0–5: trzy próby pompką; 6–10: mocny nacisk rozsuwa skałę; 11–15: odpuścić zawór.
  const valve = t >= 10 && t < 13
  return draw(...splitterAt(0, gap, down), [stander(valve ? 'mid' : 'right'), 0, 0],
    ...line([6, 3], valve ? [PUMP_AT - 1, 4] : [PUMP_AT - 1, 1 + down], 'g'))
}

const splitter: Act = {
  name: 'rozpieranie skały',
  who: ['Lont'],
  intro: [
    // Głaz z rozpierakiem, przewodem i pompką wjeżdża z prawej.
    ...SLIDE.map(dx => draw(...splitterAt(dx), [STAND, 0, 0])),
    draw(...splitterAt(0), [stander('right', 'g'), 0, 0]),
    draw(...splitterAt(0), [stander('right'), 0, 0], ...line([6, 3], [7, 2], 'g')),
    splitting(0),
  ],
  length: PUMP_DOWN.length,
  loop: splitting,
}

export const PICK_ACTS: Act[] = [rock, shovel, auger, undermine, splitter]

files.hooks/acts/plan.ts:
import { SQUAT, dots, draw, head, lerp, line, stander, stroll } from '../stage'
import type { Act, Frame, Layer, Look, Point } from '../stage'

// Planowanie: mapa na sztaludze, plan bitwy patykiem na ziemi, lista z odhaczaniem, makieta z pionkami.
// Rekwizyt wjeżdża albo spada, kartka rozwija się wiersz po wierszu; zejście cofa to samo.

// ——— Mapa na sztaludze ———
// Węgiel kreśli szlak kropka po kropce, czerwony krzyżyk na celu, potem szmata ściera szlak od początku.
const ROUTE: readonly Point[] = [[9, 4], [10, 3], [11, 3], [12, 4], [13, 3], [14, 2], [15, 2], [16, 3], [17, 2], [18, 1]]
const PEAKS: readonly Point[] = [[12, 1], [11, 2], [13, 2]]
const EASEL: Frame = ['.hhhhhhhhhh.', 'h..........h', 'h..........h', 'h..........h', 'h..........h', '.h........h.']

// Sztaluga przesunięta o `dx`, z kartką rozwiniętą na `rows` wierszy.
function easel(dx: number, rows: number): Layer[] {
  const sheet: Layer[] = rows > 0 ? [[Array.from({ length: rows }, () => 'pppppppppp'), 9 + dx, 0]] : []
  const peaks = rows === 5 ? dots(PEAKS, 'k') : []
  return [[EASEL, 8 + dx, 0], ...sheet, ...peaks]
}

function easelLoop(t: number): Frame {
  // 25 klatek: 10 kropek szlaku, chwila nad gotową mapą, 10 klatek ścierania od początku.
  const drawn = Math.min(t, ROUTE.length)
  const wiped = Math.max(0, t - 14)
  const route = ROUTE.slice(wiped, drawn)
  const goal = drawn === ROUTE.length && wiped < ROUTE.length ? dots([ROUTE[ROUTE.length - 1]!], 'R') : []
  return draw(...easel(0, 5), ...dots(route, 'n'), ...goal, [stander(t > 14 ? 'right' : 'mid', 'gg'), 0, 0])
}

const easelAct: Act = {
  name: 'sztaluga',
  intro: [
    // Pusta sztaluga wjeżdża z prawej, kartka rozwija się z górnej listwy, Krux podnosi węgiel.
    ...[12, 8, 4, 0].map(dx => draw(...easel(dx, 0), [stander('right'), 0, 0])),
    ...[1, 2, 3, 4].map(rows => draw(...easel(0, rows), [stander('right'), 0, 0])),
    draw(...easel(0, 5), [stander('mid', 'g'), 0, 0]),
  ],
  length: 25,
  loop: easelLoop,
}

// ——— Plan bitwy patykiem na ziemi ———
// Krux kuca i kreśli w piachu strzałę natarcia i wieżę wroga, potem zamiata rysunek patykiem.
const HALF: Frame = ['.gggg.', 'grggrg', '.tggt.', 'bbbbbbg', '.bGGb.', 'GG..GG']
const SHOULDER_LOW: Point = [6, 4]
const SKETCH: readonly Point[] = [
  // Strzała natarcia.
  [9, 4], [10, 4], [11, 4], [12, 4], [13, 4], [12, 5],
  // Wieża wroga z blankami.
  [17, 5], [17, 4], [18, 5], [19, 5], [19, 4],
]
const SKETCHED = SKETCH.length

// Krux drepcze w kucki za czubkiem patyka, więc ręka zostaje krótka.
function crouchAt(tip: Point): number {
  return Math.max(0, tip[0] - 11)
}

// Ręka nad rysunkiem w wierszu 2, piksel na lewo od czubka; patyk z dłoni do ziemi, czubek ciemny.
function stick(tip: Point): Layer[] {
  const hand: Point = [tip[0] - 1, 2]
  const shoulder: Point = [SHOULDER_LOW[0] + crouchAt(tip), SHOULDER_LOW[1]]
  return [...line(shoulder, hand, 'g'), ...line(hand, tip, 'h').slice(1, -1), [['x'], tip[0], tip[1]]]
}

function groundLoop(t: number): Frame {
  // 26 klatek: 11 kresek, 4 klatki namysłu, 11 klatek zamiatania od końca.
  const n = SKETCHED
  const shown = t < n ? t + 1 : t < n + 4 ? n : 2 * n + 3 - t
  const tip = SKETCH[Math.min(n - 1, t < n ? t : t < n + 4 ? n - 1 : shown)]!
  const look: Look = t >= n && t < n + 4 ? 'mid' : 'right'
  const x = crouchAt(tip)
  return draw(...dots(SKETCH.slice(0, shown), 'q'), [SQUAT, x, 0], [head(look), x, 1], ...stick(tip))
}

const ground: Act = {
  name: 'patyk',
  intro: [
    // Rozejrzeć się, przykucnąć, wyciągnąć patyk zza fartucha i opuścić go do ziemi.
    draw([stander('right'), 0, 0]),
    draw([HALF, 0, 0]),
    draw([SQUAT, 0, 0]),
    draw([SQUAT, 0, 0], ...line([7, 4], [7, 5], 'h')),
    draw([SQUAT, 0, 0], ...line([7, 4], [8, 3], 'h')),
    draw([SQUAT, 0, 0], ...line(SHOULDER_LOW, [7, 2], 'g'), ...line([8, 2], [9, 3], 'h')),
    draw([SQUAT, 0, 0], [head('right'), 0, 1], ...line(SHOULDER_LOW, [8, 2], 'g'), ...line([8, 3], [9, 3], 'h')),
  ],
  length: 2 * SKETCHED + 4,
  loop: groundLoop,
}

// ——— Lista roboty na tablicy ———
const BX = 10
const BOARD: Frame = ['hhhhhhhhh', 'h.......h', 'h.......h', 'h.......h', 'h.......h', '.h.....h.']
const ITEMS = ['nnpn', 'npnn', 'nnnp', 'npnp']
const STAND_AT = 3
const SHOULDER: Point = [9, 3]

// Kartka na tablicy: `rows` wierszy od góry, `ticked` odhaczonych pozycji, `edge` to brzeg nowej kartki.
function sheet(rows: number, ticked: number, fresh: number): Layer[] {
  const lines = ITEMS.slice(0, rows).map((ink, i) => `${i < ticked && i >= fresh ? 'f' : 'm'}p${ink}p`)
  const edge: Layer[] = fresh > 0 && fresh < 4 ? [[['jjjjjjj'], BX + 1, fresh + 1]] : []
  return [[lines, BX + 1, 1], ...edge]
}

function board(y: number, rows: number, ticked = 0, fresh = 0): Layer[] {
  return [[BOARD, BX, y], ...sheet(rows, ticked, fresh).map(([s, x, yy]) => [s, x, yy + y] as Layer)]
}

function listLoop(t: number): Frame {
  // 18 klatek: przy każdej z 4 pozycji ręka staje, stawia znak i schodzi niżej;
  // potem nowa kartka zjeżdża z góry, a ręka wraca do pierwszej pozycji.
  const item = Math.min(3, Math.floor(t / 3))
  const ticking = t < 12
  const ticked = ticking ? item + (t % 3 === 2 ? 1 : 0) : 4
  const fresh = ticking ? 0 : Math.min(4, t - 11)
  const hand: Point = ticking ? [11, item + 1] : [11, lerp(4, 1, (t - 11) / 6)]
  return draw(...board(0, 4, ticked, fresh), [stander(ticking ? 'right' : 'mid'), STAND_AT, 0], ...line(SHOULDER, hand, 'g'))
}

const list: Act = {
  name: 'lista',
  intro: [
    // Tablica spada z góry i siada na nóżkach, kartka zjeżdża, Krux podchodzi z węglem.
    ...[-5, -3, -1, 1, 0].map(y => draw(...board(y, 0), [stander(y < 0 ? 'mid' : 'right'), 0, 0])),
    ...[1, 2, 3, 4].map(rows => draw(...board(0, rows), [stander('right'), 0, 0])),
    ...stroll(STAND_AT, board(0, 4)),
    draw(...board(0, 4), [stander('right'), STAND_AT, 0], ...line(SHOULDER, [10, 2], 'g')),
  ],
  length: 18,
  loop: listLoop,
}

// ——— Makieta z pionkami ———
// Na stole stoją pionki; Krux przestawia jeden, drugi, waha się i cofa oba ruchy.
const TX = 9
const TABLE: Frame = ['', '', '', 'hhhhhhhhhhh', '.x.......x.', '.x.......x.']
const MX = 2
const ARM_FROM: Point = [8, 3]
type Pawn = { cell: string; x: number }
const PAWNS: readonly Pawn[] = [
  { cell: 'R', x: 11 },
  { cell: 'y', x: 13 },
  { cell: 'j', x: 17 },
]
// Ruchy: który pionek, skąd, dokąd.
const MOVES: readonly (readonly [number, number, number])[] = [
  [1, 13, 15],
  [0, 11, 13],
  [0, 13, 11],
  [1, 15, 13],
]
const MOVE = 8

function pawnLayers(dx: number, pawns: readonly Pawn[], lifted = -1, liftX = 0, liftY = 1): Layer[] {
  return pawns.map((p, i) => (i === lifted ? [[p.cell, p.cell], liftX + dx, liftY] : [[p.cell, p.cell], p.x + dx, 1]) as Layer)
}

function table(dx: number, pawns: readonly Pawn[] = PAWNS, ...lift: [number, number, number] | []): Layer[] {
  return [[TABLE, TX + dx, 0], ...pawnLayers(dx, pawns, ...lift)]
}

function modelLoop(t: number): Frame {
  // 32 klatki: 4 ruchy po 8 — namysł, sięgnięcie, uniesienie, dwa kroki, odstawienie, cofnięcie ręki.
  const k = Math.floor(t / MOVE)
  const p = t % MOVE
  const pawns = PAWNS.map(pawn => ({ ...pawn }))
  for (const [who, , to] of MOVES.slice(0, k)) pawns[who]!.x = to
  const [who, from, to] = MOVES[k]!
  const dir = Math.sign(to - from)
  const look: Look = p < 2 ? (k % 2 === 0 ? 'right' : 'mid') : 'right'
  const orc: Layer = [stander(look), MX, 0]
  if (p < 2) return draw(...table(0, pawns), orc)
  if (p === 2) return draw(...table(0, pawns), orc, ...line(ARM_FROM, [from - 1, 2], 'g'))
  if (p === 7) return draw(...table(0, pawns.map((pw, i) => (i === who ? { ...pw, x: to } : pw))), orc, ...line(ARM_FROM, [9, 2], 'g'))
  const x = p === 3 ? from : p === 4 ? from + dir : to
  const y = p === 6 ? 1 : 0
  return draw(...table(0, pawns, who, x, y), orc, ...line(ARM_FROM, [x - 1, y + 1], 'g'))
}

const model: Act = {
  name: 'makieta',
  intro: [
    // Stół z pionkami wjeżdża z prawej, Krux podchodzi.
    ...[12, 9, 6, 3, 0].map(dx => draw(...table(dx), [stander('right'), 0, 0])),
    ...stroll(MX, table(0)),
  ],
  length: MOVES.length * MOVE,
  loop: modelLoop,
}

export const PLAN_ACTS: Act[] = [easelAct, ground, list, model]

